@ wren7 qemu_diff batch, seed 4, 1000 cases -- generated by model/tools/qemu_diff --gen, do not edit.
@ Link .text at 0x10000 and run from 0x10000.  Results: out_tab (64 bytes per case: r0-r12, r14, CPSR),
@ scratch (128 bytes per memory case).  Ends with three SWI 0 (qemu-user: write, write, exit).
.macro CASE i, op
	ldr r13, =in_tab+(\i*64)
	ldr r0, [r13, #60]
	msr cpsr_f, r0
	ldmia r13, {r0-r12, r14}
	.word \op
	ldr r13, =out_tab+(\i*64)
	stmia r13, {r0-r12, r14}
	mrs r0, cpsr
	str r0, [r13, #56]
.endm
.macro POOL
	b 1f
	.ltorg
1:
.endm
.text
